window.RP_SESSION={"id":"S-a61e0dc5506e","messages":[{"id":"RP-0270019","time":"2026-09-11T00:25:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아무튼, 오즈발드 윌은 길드에 있습니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270020","time":"2026-09-11T00:26:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…한가하군요.“","characters":["P-d40bea4fdee0"]},{"id":"RP-0270021","time":"2026-09-11T00:27:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오늘, 간만에 빨래를 널어볼까 하던 오즈는 아쉽게도 이미 당번에 의해 멀끔히 널어진 빨래들을 보고 아쉬움을 느낀 채 다음 일거리를 찾아 움직였습니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270022","time":"2026-09-11T00:28:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…??? 길드 빨래 또한 누군가 해뒀습니다???\n슬슬 한 번 해야될 것 같다 싶었었는데, 이 길드에는 청소를 제법 좋아하는 사람들이 여럿 있나봅니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270023","time":"2026-09-11T00:29:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"밭에 물을 주자니, 이미 흠뻑 젖어있는 밭을 보아 여기서 더 물을 주었다간 과할 것 같고…","characters":["P-d40bea4fdee0"]},{"id":"RP-0270024","time":"2026-09-11T00:30:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"마당을 쓸자니 이것마저 어제 해두어서 그리 쓸어낼 것들이 많지 않았습니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270025","time":"2026-09-11T00:30:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"보이는 쓰레기들을 주워다 버리고…","characters":["P-d40bea4fdee0"]},{"id":"RP-0270026","time":"2026-09-11T00:30:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“……정말 한가하군요…”","characters":["P-d40bea4fdee0"]},{"id":"RP-0270027","time":"2026-09-11T00:31:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈발드 윌은 다시 기약없는 휴식에 접어듭니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270028","time":"2026-09-11T00:32:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이곳 길드에는 당연히도 간간히 건강한 새끼를 낳는 소들도 없고, 그녀석들에게 가져다 주어야 할 여물도 없고.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270029","time":"2026-09-11T00:32:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"밭은 이미 누가 잘 가꾸어 두는 듯 하며 직접 찾아가 말씀을 나누어드릴 나이 든 주민 분들도 없습니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270030","time":"2026-09-11T00:33:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…”","characters":["P-d40bea4fdee0"]},{"id":"RP-0270031","time":"2026-09-11T00:34:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“늦은 밤은 어두컴컴한 숲으로 들어가 지도를 그리기에도 적절하지 않으니…”","characters":["P-d40bea4fdee0"]},{"id":"RP-0270032","time":"2026-09-11T00:37:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”문득 든 생각입니다만, 이렇게 주어지는 시간들을 허투로 흘려버리지 않기 위해 작은 취미를 하나 두는 것도 좋을 것 같습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-0270033","time":"2026-09-11T00:37:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…흠, 한 번 생각해봐야겠군요.“","characters":["P-d40bea4fdee0"]},{"id":"RP-0270034","time":"2026-09-11T00:39:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈발드는 근처에서 작은 나뭇가지들과 잎사귀, 클레이의 도움을 받아 만든 진흙덩이 조금을 집어들고 길드로 돌아갑니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270035","time":"2026-09-11T00:39:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그리 손재주가 좋은 편은 아니지만… 이대로 가만히 시간을 보내기에는 좀이 쑤시나봅니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0270036","time":"2026-09-11T00:39:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d40bea4fdee0"]},{"id":"RP-0270037","time":"2026-09-11T00:39:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
